function ReconciliationAccountSettingsPage({route}: ReconciliationAccountSettingsPageProps) {
    const {policyID, connection} = route.params;

    const styles = useThemeStyles();
    const {translate} = useLocalize();

    const workspaceAccountID = PolicyUtils.getWorkspaceAccountID(policyID);
    const connectionName = AccountingUtils.getConnectionNameFromRouteParam(connection);

    const [bankAccountList] = useOnyx(ONYXKEYS.BANK_ACCOUNT_LIST);
    const [cardSettings] = useOnyx(`${ONYXKEYS.COLLECTION.PRIVATE_EXPENSIFY_CARD_SETTINGS}${workspaceAccountID}`);
    const paymentBankAccountID = cardSettings?.paymentBankAccountID ?? 0;

    const selectedBankAccount = useMemo(() => bankAccountList?.[paymentBankAccountID.toString()], [paymentBankAccountID, bankAccountList]);
    const bankAccountNumber = useMemo(() => selectedBankAccount?.accountData?.accountNumber ?? '', [selectedBankAccount]);
    const settlementAccountEnding = getLastFourDigits(bankAccountNumber);

    const sections = useMemo(() => {
        if (!bankAccountList || isEmptyObject(bankAccountList)) {
            return [];
        }
        const eligibleBankAccounts = CardUtils.getEligibleBankAccountsForCard(bankAccountList);

        const data = eligibleBankAccounts.map((bankAccount) => ({
            text: bankAccount.title,
            value: bankAccount.accountData?.bankAccountID,
            keyForList: bankAccount.accountData?.bankAccountID?.toString(),
            isSelected: bankAccount.accountData?.bankAccountID === paymentBankAccountID,
        }));
        return [{data}];
    }, [bankAccountList, paymentBankAccountID]);

    const selectBankAccount = (newBankAccountID?: number) => {
        Card.updateSettlementAccount(workspaceAccountID, policyID, newBankAccountID, paymentBankAccountID);
        Navigation.goBack();
    };

    return (
        <ConnectionLayout
            displayName={ReconciliationAccountSettingsPage.displayName}
            headerTitle="workspace.accounting.reconciliationAccount"
            accessVariants={[CONST.POLICY.ACCESS_VARIANTS.ADMIN, CONST.POLICY.ACCESS_VARIANTS.PAID]}
            policyID={policyID}
            featureName={CONST.POLICY.MORE_FEATURES.ARE_CONNECTIONS_ENABLED}
            contentContainerStyle={[styles.flex1, styles.pb2]}
            connectionName={connectionName}
            shouldUseScrollView={false}
        >
            <Text style={[styles.textNormal, styles.mb5, styles.ph5]}>{translate('workspace.accounting.chooseReconciliationAccount.chooseBankAccount')}</Text>
            <Text style={[styles.textNormal, styles.mb6, styles.ph5]}>
                {translate('workspace.accounting.chooseReconciliationAccount.accountMatches')}
                <TextLink onPress={() => Navigation.navigate(ROUTES.WORKSPACE_EXPENSIFY_CARD_SETTINGS_ACCOUNT.getRoute(policyID))}>
                    {translate('workspace.accounting.chooseReconciliationAccount.settlementAccount')}
                </TextLink>
                {translate('workspace.accounting.chooseReconciliationAccount.reconciliationWorks', {lastFourPAN: settlementAccountEnding})}
            </Text>

            <SelectionList
                sections={sections}
                onSelectRow={({value}) => selectBankAccount(value)}
                ListItem={RadioListItem}
                initiallyFocusedOptionKey={paymentBankAccountID.toString()}
            />
        </ConnectionLayout>
    );
}

function ChooseTransferAccountPage() {
    const [walletTransfer, walletTransferResult] = useOnyx(ONYXKEYS.WALLET_TRANSFER);

    const styles = useThemeStyles();
    const {translate} = useLocalize();
    /**
     * Go back to transfer balance screen with the selected bank account set
     * @param event Click event object
     * @param accountType of the selected account type
     * @param account of the selected account data
     */
    const selectAccountAndNavigateBack = (accountType?: string, account?: AccountData) => {
        PaymentMethods.saveWalletTransferAccountTypeAndID(
            accountType ?? '',
            (accountType === CONST.PAYMENT_METHODS.PERSONAL_BANK_ACCOUNT ? account?.bankAccountID?.toString() : account?.fundID?.toString()) ?? '',
        );
        Navigation.goBack(ROUTES.SETTINGS_WALLET_TRANSFER_BALANCE);
    };

    const navigateToAddPaymentMethodPage = () => {
        if (walletTransfer?.filterPaymentMethodType === CONST.PAYMENT_METHODS.DEBIT_CARD) {
            Navigation.navigate(ROUTES.SETTINGS_ADD_DEBIT_CARD);
            return;
        }
        BankAccounts.openPersonalBankAccountSetupView();
    };

    const [bankAccountsList] = useOnyx(ONYXKEYS.BANK_ACCOUNT_LIST);
    const selectedAccountID = walletTransfer?.selectedAccountID;
    const data = useMemo(() => {
        const options = Object.values(bankAccountsList ?? {}).map((bankAccount): BankAccountListItem => {
            const bankName = (bankAccount.accountData?.additionalData?.bankName ?? '') as BankName;
            const bankAccountNumber = bankAccount.accountData?.accountNumber ?? '';
            const bankAccountID = bankAccount.accountData?.bankAccountID ?? bankAccount.methodID;
            const {icon, iconSize, iconStyles} = getBankIcon({bankName, styles});
            return {
                value: bankAccountID,
                text: bankAccount.title,
                leftElement: icon ? (
                    <View style={[styles.flexRow, styles.alignItemsCenter, styles.mr3]}>
                        <Icon
                            src={icon}
                            width={iconSize}
                            height={iconSize}
                            additionalStyles={iconStyles}
                        />
                    </View>
                ) : null,
                alternateText: `${translate('workspace.expensifyCard.accountEndingIn')} ${getLastFourDigits(bankAccountNumber)}`,
                keyForList: bankAccountID?.toString(),
                isSelected: bankAccountID?.toString() === selectedAccountID,
                bankAccount,
            };
        });
        return options;
    }, [bankAccountsList, selectedAccountID, styles, translate]);

    if (isLoadingOnyxValue(walletTransferResult)) {
        return <FullscreenLoadingIndicator />;
    }

    return (
        <ScreenWrapper testID={ChooseTransferAccountPage.displayName}>
            <HeaderWithBackButton
                title={translate('chooseTransferAccountPage.chooseAccount')}
                onBackButtonPress={() => Navigation.goBack(ROUTES.SETTINGS_WALLET_TRANSFER_BALANCE)}
            />

            <SelectionList
                sections={[{data}]}
                ListItem={RadioListItem}
                onSelectRow={(value) => {
                    const accountType = value?.bankAccount?.accountType;
                    const accountData = value?.bankAccount?.accountData;
                    selectAccountAndNavigateBack(accountType, accountData);
                }}
                shouldSingleExecuteRowSelect
                shouldUpdateFocusedIndex
                initiallyFocusedOptionKey={walletTransfer?.selectedAccountID?.toString()}
                listFooterContent={
                    <MenuItem
                        onPress={navigateToAddPaymentMethodPage}
                        title={
                            walletTransfer?.filterPaymentMethodType === CONST.PAYMENT_METHODS.PERSONAL_BANK_ACCOUNT
                                ? translate('paymentMethodList.addNewBankAccount')
                                : translate('paymentMethodList.addNewDebitCard')
                        }
                        icon={Expensicons.Plus}
                    />
                }
            />
        </ScreenWrapper>
    );
}

function SageIntacctMappingsTypePage({route}: SageIntacctMappingsTypePageProps) {
    const {translate} = useLocalize();
    const styles = useThemeStyles();

    const mappingName: SageIntacctMappingName = route.params.mapping;
    const policy = usePolicy(route.params.policyID);
    const policyID = policy?.id ?? '-1';

    const {config} = policy?.connections?.intacct ?? {};
    const {mappings, pendingFields, export: exportConfig} = config ?? {};

    const selectionOptions = useMemo<SelectorType[]>(() => {
        const mappingOptions: SelectorType[] = [];
        if (
            !([CONST.SAGE_INTACCT_CONFIG.MAPPINGS.CUSTOMERS, CONST.SAGE_INTACCT_CONFIG.MAPPINGS.PROJECTS] as string[]).includes(mappingName) &&
            exportConfig?.reimbursable !== CONST.SAGE_INTACCT_REIMBURSABLE_EXPENSE_TYPE.VENDOR_BILL
        ) {
            mappingOptions.push({
                value: CONST.SAGE_INTACCT_MAPPING_VALUE.DEFAULT,
                text: translate('workspace.intacct.employeeDefault'),
                alternateText: translate('workspace.common.appliedOnExport'),
                keyForList: CONST.SAGE_INTACCT_MAPPING_VALUE.DEFAULT,
                isSelected: mappings?.[mappingName] === CONST.SAGE_INTACCT_MAPPING_VALUE.DEFAULT,
            });
        }
        mappingOptions.push(
            ...[
                {
                    value: CONST.SAGE_INTACCT_MAPPING_VALUE.TAG,
                    text: translate('workspace.common.tags'),
                    alternateText: translate('workspace.common.lineItemLevel'),
                    keyForList: CONST.SAGE_INTACCT_MAPPING_VALUE.TAG,
                    isSelected: mappings?.[mappingName] === CONST.SAGE_INTACCT_MAPPING_VALUE.TAG,
                },
                {
                    value: CONST.SAGE_INTACCT_MAPPING_VALUE.REPORT_FIELD,
                    text: translate('workspace.common.reportFields'),
                    alternateText: translate('workspace.common.reportLevel'),
                    keyForList: CONST.SAGE_INTACCT_MAPPING_VALUE.REPORT_FIELD,
                    isSelected: mappings?.[mappingName] === CONST.SAGE_INTACCT_MAPPING_VALUE.REPORT_FIELD,
                },
            ],
        );

        return mappingOptions;
    }, [exportConfig?.reimbursable, mappingName, mappings, translate]);

    const updateMapping = useCallback(
        ({value}: SelectorType) => {
            updateSageIntacctMappingValue(policyID, mappingName, value as SageIntacctMappingValue, mappings?.[mappingName]);
            Navigation.goBack(ROUTES.POLICY_ACCOUNTING_SAGE_INTACCT_TOGGLE_MAPPINGS.getRoute(policyID, mappingName));
        },
        [mappingName, policyID, mappings],
    );

    return (
        <SelectionScreen
            policyID={policyID}
            accessVariants={[CONST.POLICY.ACCESS_VARIANTS.ADMIN, CONST.POLICY.ACCESS_VARIANTS.PAID]}
            featureName={CONST.POLICY.MORE_FEATURES.ARE_CONNECTIONS_ENABLED}
            displayName={SageIntacctMappingsTypePage.displayName}
            sections={[{data: selectionOptions}]}
            listItem={RadioListItem}
            connectionName={CONST.POLICY.CONNECTIONS.NAME.SAGE_INTACCT}
            onSelectRow={updateMapping}
            initiallyFocusedOptionKey={mappings?.[mappingName]}
            onBackButtonPress={() => Navigation.goBack(ROUTES.POLICY_ACCOUNTING_SAGE_INTACCT_TOGGLE_MAPPINGS.getRoute(policyID, mappingName))}
            title="workspace.common.displayedAs"
            pendingAction={settingsPendingAction([mappingName], pendingFields)}
            errors={ErrorUtils.getLatestErrorField(config ?? {}, mappingName)}
            errorRowStyles={[styles.ph5, styles.pv3]}
            onClose={() => Policy.clearSageIntacctErrorField(policyID, mappingName)}
        />
    );
}

